const fs = require('fs');
const readline = require('readline');

const logFile = 'C:\\Users\\computer\\.gemini\\antigravity\\brain\\572b5ef2-df3a-452d-b484-217992cd5adc\\.system_generated\\logs\\transcript_full.jsonl';

const rl = readline.createInterface({
  input: fs.createReadStream(logFile),
  crlfDelay: Infinity
});

let lineNum = 0;
rl.on('line', (line) => {
  lineNum++;
  if (line.includes('btn-add-cart')) {
    console.log(`Line ${lineNum}: length=${line.length}`);
    // Print around the matches if short, or if it's the full file, let's write it to a debug file.
    if (line.length > 5000) {
      try {
        const obj = JSON.parse(line);
        let code = '';
        if (obj.content) code = obj.content;
        else if (obj.tool_calls) {
          obj.tool_calls.forEach(tc => {
            if (tc.function && tc.function.arguments) {
              const args = JSON.parse(tc.function.arguments);
              if (args.CodeContent) code = args.CodeContent;
            }
          });
        }
        if (code) {
          fs.writeFileSync(`C:\\Users\\computer\\Desktop\\chef cozinha\\garcom_with_btn_add_cart_${lineNum}.html`, code, 'utf8');
          console.log(`Wrote candidate to garcom_with_btn_add_cart_${lineNum}.html`);
        }
      } catch(e) {
        console.error('Error on line', lineNum, e.message);
      }
    }
  }
});
